INSERT INTO `contacts` (`contacts_id`, `nom`, `prenom`, `Tel`, `Email`, `the_type`, `Societe`, `Ville_D_origine`, `Adresse`, `Etat_Social`, `date_de_naissance`, `Ideologie`, `Commentaire`, `social_media`, `gender`, `path`, `educational_level`, `keywords`, `spouse`, `children`, `siblings`, `parents`, `maternal_relatives`, `paternal_relatives`, `grandparents`, `friends`, `name_in_arabic`, `updated_at`, `created_at`, `cousins`, `Author`) VALUES
(1, 'Elhaouss', 'Mona', NULL, 'mona.elhouas@gmai.com', 'collegue', 'Telexpert', 'Sale', 'Sale', 'Fiancee', '1997-01-01', NULL, 'لم تتمكن من بيع أي شيء عندما كانت تعمل في مركز الاتصال، إلا في اليوم الأخير عندما ساعدتها في إقناع أول زبون لها،\r\nوأنا أسجل معلوماته طلبت منها أن تقبلني ففعلت بدون تردد، لكنها لم تعجب بالأمر، فضلت تتجاهلني، وادعت أنها مخطوبة،', NULL, 'Female', '', '2nd Year of Baccalaureate', NULL, NULL, NULL, 'إقبال الهاوس', NULL, NULL, NULL, NULL, NULL, 'منى الهاوس', '2024-12-29 12:30:40', '2024-12-08 23:00:00', NULL, ''),
(2, 'Lachgar_Tagdicht', 'Khadija', '0671-665637', '', 'Ami (e)', NULL, 'Tagdicht', 'مكناس', 'Celibataire', NULL, '', NULL, NULL, 'Female', '', '4th Year of Primary School', 'تكضيشت إيساكن، نيت ناجيم، تكناتين', NULL, NULL, 'إبراهيم لشكر, محمد لشكر, الحسين لشكر, حبيبة لشكر', 'الناجيم لشكر، عائشة لشكر', 'إبراهيم المخروبي أفلاي،', NULL, NULL, NULL, 'خديجة لشكر', '2024-12-29 18:48:42', '2024-12-08 23:00:00', NULL, '1,7,8,9'),
(3, 'Abourou', 'Soukaina', '0682-766880//0608-54', 'abourousoukaina1998@gmail.com', 'collegue', 'Telexpert,ADM', NULL, 'Rabat', 'Fiancee', NULL, NULL, 'قامت بحظري من الفيسبوك بسبب مقال: \"في مدح الفساد وجمال اللحية\"، أصلها شلحة ولكن لا تتحدثها', NULL, 'Female', '3Soukaina_Abourou1.webp,3Soukaina_Abourou2.webp,3Soukaina_Abourou3.webp,3Soukaina_Abourou4.webp,3Soukaina_Abourou5.webp', 'Post-Baccalaureate', 'مركز الأتصال', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'سارة دحو', 'سكينة أبورو', '2024-12-29 12:30:40', '2024-12-08 23:00:00', NULL, ''),
(4, 'ADM', 'Ahlam', '0762-347835', '', 'collegue', 'ADM', NULL, 'Rabat', 'Celibataire', NULL, 'محجبة، تصلي في مركز الاتصال', 'فتاة اجتماعية، كانت تراسلني وتتصل بي حتى بعد مغادرت ADM Value، وتعاطفت معي، وكانت تنتقد عادل نيكي.\r\nهي دكتورة في البيولوجية، أطروحتها حول بكتيريا هضمية وعلاقتها بالسرطان، هاجرت لفرنسا لأجل تدريب', NULL, 'Female', '4Ahlam_ADM1.webp', 'Post-Baccalaureate', 'medcin du monde، أطباء العالم', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'أحلام', '2024-12-29 12:30:40', '2024-12-08 23:00:00', NULL, ''),
(5, 'ait_Bihi', 'Khadija', '0654-199758', 'kaitbihi090@gmail.com', 'collegue', 'Telexpert', NULL, 'Rabat', 'Marie(e)', '1992-01-01', 'محجبة', 'اجتماعية، بمجرد ما عرفت كنيتي، عرفت أنني من تكضيشت وسألتني عن إسم أبي وعائلة محسن (أيت سي لحس) الذين غيروا كنيتهم من بوكلزيم إلى محسن.\r\nسمعت أنها متزوجة، ويبدو أيضا أنها أم.\r\nتخاف القطط بشدة.', NULL, 'Female', '', 'Post-Baccalaureate', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'خديجة أيت بيهي', '2024-12-29 12:30:40', '2024-12-08 23:00:00', NULL, ''),
(6, 'Alaoui', 'Zainab', '0693-371943', '', 'collegue', 'Telexpert', 'Rabat', 'Rabat', 'Celibataire', NULL, NULL, NULL, NULL, 'Female', '', 'Post-Baccalaureate', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'زينب علوي', '2024-12-29 12:30:40', '2024-12-08 23:00:00', NULL, ''),
(7, 'Alaoui_Hakim', 'Farah', '0681-174353', 'farahalaouihk@gmail.com', 'Code', 'Telexpert', 'Rabat', 'Rabat', 'Celibataire', '1997-01-01', NULL, 'تحب الكلاب وتكره القطط،\r\nاجتماعية، هي التي اقترحت علي شركة للبرمجة لا تشترط أي ديبلوم،\r\nكانت متأكدة أنهم لن يمسكوا الCV ويقولوا: غادي نعيطو ليك،\r\nولكن حينها كنت جد غبي في البرمجة', NULL, 'Female', '7Farah_Alaoui_Hakim1.webp', '2nd Year of Baccalaureate', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'فرح علوي حكيم', '2024-12-29 12:30:40', '2024-12-08 23:00:00', NULL, ''),
(8, 'Bouaoud', 'Lamia', '', 'lamiaabououd@gmail.com', 'collegue', 'Telexpert', NULL, 'Rabat', 'Marie(e)', NULL, 'محجبة', 'فتاة محجبة، معروفة بكونها تشكو بشكل شديد من آلام الدورة الشهرية، لدرجة أن الجميع يعلم بأمرها،\r\nعائلتها يذهبون للإماراة لسبب ما، ويثركونها وحدها في البيت، قالت ذلك مرة وهي تتحدث لنا أثناء الفطور في مركز الاتصال،\r\nقال لي ربيع ربيع تريبو أنها تزوجت من حسين ا', NULL, 'Female', '8Lamia_Bouaoud1.webp,8Lamia_Bouaoud2.webp,8Lamia_Bouaoud3.webp,8Lamia_Bouaoud4.webp', '2nd Year of Baccalaureate', NULL, 'حسين الشادلي البركاوي', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'لمياء بوعود', '2024-12-29 12:30:40', '2024-12-08 23:00:00', NULL, ''),
