INSERT INTO `examitems` (`premary_id`, `qsts_id`, `exam_number`, `qst_1st_line`, `qsts`, `choice1`, `choice2`, `choice3`, `correct_answer`, `if_choising_1`, `if_choising_2`, `if_choising_3`, `if_choising_correct`, `the_type`, `qst_img`, `img_if_wrong_answer`, `img_if_right_answer`, `if_its_wrong_answer`, `dir`, `mark`, `created_at`, `updated_at`) VALUES
(1, 7, 1, 'بماذا يرمز لعنصر الهيدروجين ؟', '', '', '', '', 'H', 'تنبيه: لا يجب كتابة أي شي آخر في مكان الإجابة غير رمز الهيدروجين فقط!', '', '', 'أحسنت .. \"H\" : هو رمز الهيدروجين، وهو أول عنصر في الجدولي الدوري\r\n', 'text', 'atome hydrogène.webp', '', '', 'ليس رمزا للهيدروجين، رمز الهيدروجين يتكون من حرف واحد لاتيني كبير(MAJUSCULE)، حاول مرة أخر !<br>', 'rtl', '2', '2024-12-08 23:00:00', '2024-12-08 23:00:00'),
(2, 1, 1, 'أي من العبارات أسفله صحيح ؟', '', '', 'تتكون الذرة (بالفرنسة Atome) من الماء والثراب ', 'تتكون الذرة (بالفرنسة Atome) من الماء والأملاح المعدنية', 'تتكون الذرة (بالفرنسية Atome) من نواة تحيط حولها إلكترونات.', 'صحيح، جميع الذرات تتكون من نواةشحنتها موجبة وتيحيط بها إلكترونات سالبة', '', '', 'صحيح، جميع الذرات تتكون من نواةشحنتها موجبة وتيحيط بها إلكترونات سالبة', 'radio', 'atom-2.webp', '', '', 'إجابة خاطئة:<br>\r\nسأساعدك قليلا هذه المرة .. الذرة هي شيء صغيييير جدا ولا يرى بالعين المجردة وتتكون الدرة من نواة موجبة الشحنة تحيط بها إلكترونات شحنتها سالبة.', 'rtl', '1.5', '2024-12-08 23:00:00', '2024-12-08 23:00:00'),
(3, 2, 1, 'كم عدد أعمدة الجدول الدوري للعناصر الكميائية؟', '', '', '', '', '18', '', '', '', 'أحسنت .. في الجدول الدوري يوجد 18 عمودا ..', 'text', 'periodic_table.webp', '', 'good.gif', 'يبدو أنك لم تحسبها جيدا .. <br>\r\nلمساعدك أعرض عليك صورة للجدول الدوري .. أحسب عدد الأعمدة فيه قبل الإجابة ...', 'rtl', '2', '2024-12-08 23:00:00', '2024-12-08 23:00:00'),
(4, 3, 1, 'ما اسم أول عائلة في الجدول الدوري للعناصر الكميائية؟', '', '', '', '', 'Alcalin', '', '', '', 'أحسنت انت بطل في الكمياء ..', 'text', 'periodic_table.webp', '', '', 'الجواب خطأ ، فكر جيد ا', 'rtl', '2', '2024-12-08 23:00:00', '2024-12-08 23:00:00'),
(5, 4, 1, 'ما إسم العناصر الموجودة في آخر عمود في الجدول الدوري؟', '', 'الهالوجينات', 'الغازات السامة', 'عائلة الهيليوم', 'الغازات النبيلة', '', '', '', 'رائع .. يبدو أنك ستصبح من كبار علماء الكمياء ..  :)', 'radio', 'periodic_table.webp', 'periodic_table.webp', 'periodic_table.webp', 'لا، فكر مرة أخرى .. ثم حاول مجددا', 'rtl', '1.5', '2024-12-08 23:00:00', '2024-12-08 23:00:00'),
(6, 5, 1, 'ما هو تعريف الغازات النبيلة؟', '', '', '', '', 'الغازات النبيلة :هي مجموعة العناصر الكميائية الموجود في العمود الأخير في الجدول الدوري للعناصر الكميائية، وتتميز بكون الطبقة الخارجية لهذه العناصر مشبعة بالإلكترونات.', '', '', '', 'جيد .. إجابتك لا بأس بها :) <br>الغازات النبيلة :هي مجموعة العناصر الكميائية الموجود في العمود الأخير في الجدول الدوري للعناصر الكميائية، وتتميز بكون الطبقة الخارجية لهذه العناصر مشبعة بالإلكترونات.', 'textarea', 'noble_gases.webp', 'noble_gases.webp', '', 'التعريف الذي كتبته، لا يصف الغازات النبيلة بشكل كامل، أنصحك بمراجعة الدرس المتعلق بهذه الغازات، إذا وجدت صعوبة في الإجابة على هذا السؤال يمكنك نسخ السؤال وإرساله لإدارة الموقع، في نافدة \"إتصل بنا\" ... سنقوم بمساعدتك عن طريق الإيميل الخاص بك.', 'rtl', '3', '2024-12-08 23:00:00', '2024-12-08 23:00:00'),
(7, 6, 1, 'ما هو رمز ثنائي أكسيد الكربون ؟', NULL, 'H', '2CO', 'O2', 'CO2', '', '', '', 'نعم رمز ثنائي أكسيد الكربون هو CO2  ...', 'radio', 'CO2.webp', '', '', 'الإجابة خاطئة .. حاول مرة أخرى', 'rtl', '1', '2024-12-08 23:00:00', '2024-12-10 20:10:49'),
(8, 1, 2, 'Complete la phrase suivante:', 'Le plus grand réservoir d\'eau sur terre se trouve dans les ................ et les mers.', 'volume', 'gaz', 'récipient', 'océans', 'Ce n\'pas la bonne réponse, car: <br>\r\nLe volume est la mesure de l\'espace occupé par un objet.', 'Ce n\'pas la bonne réponse , continue à travailler dur!', 'Ce n\'pas la bonne réponse , continue à travailler dur', 'Félicitations pour avoir répondu à ta première questions ! Continue ainsi et tu  apprendras  beaucoup de choses intéressantes', 'radio', 'World_map_ocean.webp', '', '', 'Ce n\'ai pas la bonne réponse, mais tu peux toujours te rattraper.', 'ltr', '1', '2024-12-08 23:00:00', '2024-12-08 23:00:00'),
