--
-- Triggers `products`
--
DELIMITER $$
CREATE TRIGGER `trg_fix_price_before_discount` BEFORE INSERT ON `products` FOR EACH ROW BEGIN
  IF NEW.price_before_discount IS NULL OR NEW.price_before_discount < NEW.selling_price THEN
    SET NEW.price_before_discount = ROUND(NEW.selling_price * 1.25);
  END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_fix_price_before_discount_update` BEFORE UPDATE ON `products` FOR EACH ROW BEGIN
  IF NEW.price_before_discount IS NULL OR NEW.price_before_discount < NEW.selling_price THEN
    SET NEW.price_before_discount = ROUND(NEW.selling_price * 1.25);
  END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_set_price_before_discount` BEFORE INSERT ON `products` FOR EACH ROW BEGIN
  IF NEW.price_before_discount IS NULL OR NEW.price_before_discount = 0 THEN
    SET NEW.price_before_discount = NEW.selling_price * 1.25;
  END IF;
END
$$
DELIMITER ;

